#[effects(alloc)]
fn konst(ev: &mut Eval, path: &str, f: usize) -> Option<CVal>
    decreases f,
{
    if f == 0 {
        return None;
    }
    match ev.done.find(path) {
        None => {},
        Some(k) => { return ev.done.items[k].clone(); },
    }
    let mut di: usize = 0;
    match ev.defs.find(path) {
        None => { return None; },
        Some(i) => { di = i; },
    }
    if di >= ev.defs.items.len() {
        return None;
    }
    let unit: String = ev.defs.items[di].unit.clone();
    let c: ast::ConstDef = ev.defs.items[di].c.clone();
    if has(ev.stack.as_slice(), path) {
        let mut msg: String = String::from("constants refer to each other: ");
        let mut on: bool = false;
        for s in 0..ev.stack.len() {
            if ev.stack[s].as_str() == path {
                on = true;
            }
            if on {
                msg.push_str(ev.stack[s].as_str());
                msg.push_str(" -> ");
            }
        }
        msg.push_str(path);
        ev.done.insert(path, None);
        return None;
    }
    if !declarable(&c.ty.kind) {
        ev.diags.push(not_value(&c.ty.kind, c.ty.span));
        ev.done.insert(path, None);
        return None;
    }
    ev.stack.push(String::from(path));
    let none: Subst = Subst { names: Vec::new(), tys: Vec::new() };
    let want: Option<ast::TypeKind> = Some(norm(ev, &c.ty.kind, unit.as_str(), &none, 1000000000));
    let saved: Vec<Vec<Bind>> = std::mem::replace(&mut ev.env, Vec::new());
    let v: Option<CVal> = expr(ev, &c.value, &want, unit.as_str(), f - 1);
    ev.env = saved;
    ev.stack.pop();
    let mut ok: bool = false;
    match &v {
        None => {},
        Some(x) => { if !scalar(&c.ty.kind) || kind_text(&cval_ty(x)) == kind_text(&c.ty.kind) { ok = true; } else { let mut m2: String = String::from("expected `"); m2.push_str(kind_text(&c.ty.kind).as_str()); m2.push_str("`, found `"); m2.push_str(kind_text(&cval_ty(x)).as_str()); m2.push_str("`"); ev.diags.push(diag::new("E0401", c.value.span, m2.as_str())); } },
    }
    let kept: Option<CVal> = keep(v, ok);
    ev.done.insert(path, kept.clone());
    kept
}

impl Checker {
    #[effects(alloc)]
    fn impl_head(self: &mut Checker, i: &ast::TraitImpl, mp: &str) -> () {
        if i.trait_path.len() == 0 {
            return;
        }
        let name: String = path_text(i.trait_path.as_slice());
        let tspan: source::Span = span_to(i.trait_path[0].span, i.trait_path[i.trait_path.len() - 1].span);
        let found: Option<String> = self.trait_path(i.trait_path.as_slice(), mp);
        let tr: String = match found {
            None => { let help: String = match self.type_path(i.trait_path.as_slice(), mp) { None => String::from("a trait of another unit is named by full path, e.g. `unit::Shape`"), Some(tp) => types::cat5("`", name.as_str(), "` is a type; its own functions go in `impl ", name.as_str(), " { .. }`"), }; let d: diag::Diag = self.unknown_trait(name.as_str(), tspan, mp, help.as_str()); self.diags.push(d); return; },
            Some(x) => x,
        };
        let gens: Vec<types::TParam> = self.tparams_of(i.generics.as_slice(), true, mp);
        self.tparams = gens.clone();
        let head: ast::TypeKind = self.canon(&i.self_ty, mp, true, 100000);
        self.tparams = Vec::new();
        let span: source::Span = i.self_ty.span;
        if types::is_error(&head) {
            return;
        }
        let info: types::TraitImplInfo = types::TraitImplInfo { trait_path: tr.clone(), generics: gens.clone(), head: head.clone(), unit: String::from(mp), span: i.span };
        match types::param_name(&head) {
            None => {},
            Some(n) => { self.help("E0235", span, types::cat4(types::cat5("`impl<", n.as_str(), "> ", name.as_str(), " for ").as_str(), n.as_str(), types::cat3("` implements `", name.as_str(), "` for every type (a blanket impl)").as_str(), "").as_str(), types::cat5("implement it for each type: `impl ", name.as_str(), " for Point { .. }`, or bound a type parameter `T: ", name.as_str(), "` where it is used").as_str()); self.rejected_impls.push(info); return; },
        }
        let mut cb: Vec<String> = Vec::new();
        cb.push(String::from("Copy"));
        let copy: types::TParam = types::TParam { name: String::from("Self"), bounds: cb };
        if !self.targ_ok(&head, &copy, tr.as_str(), span, true) {
            return;
        }
        let ht: String = types::text_in(&head, mp);
        for g in 0..gens.len()
            invariant 0 <= g && g <= gens.len(),
        {
            if !types::mentions_param(&head, gens[g].name.as_str(), 100000) {
                let at: source::Span = if g < i.generics.len() {
                    i.generics[g].span
                } else {
                    span
                };
                self.help("E0420", at, types::cat5("type parameter `", gens[g].name.as_str(), "` of the impl does not appear in `", ht.as_str(), "`").as_str(), "remove it, or use it in the implemented type");
                self.rejected_impls.push(info);
                return;
            }
        }
        let mut seen: Vec<String> = Vec::new();
        types::params_in(&head, &mut seen, 100000);
        if !same_names(seen.as_slice(), gens.as_slice()) {
            self.help("E0420", span, types::cat3("the `impl` for `", ht.as_str(), "` takes its type parameters in order").as_str(), types::cat3("declare them in the order the type names them: `", types::join(seen.as_slice(), "`, `").as_str(), "`").as_str());
            self.rejected_impls.push(info);
            return;
        }
        let trait_unit: String = unit_of(tr.as_str());
        let type_unit: Option<String> = match types::named_path(&head) {
            None => None,
            Some(hp) => { if self.adts.has(hp.as_str()) { Some(unit_of(hp.as_str())) } else { None } },
        };
        let in_type_unit: bool = match &type_unit {
            None => false,
            Some(u) => u.as_str() == mp,
        };
        if mp != trait_unit.as_str() && !in_type_unit {
            let help: String = match &type_unit {
                None => types::cat3("move it to unit `", trait_unit.as_str(), "`"),
                Some(u) => { if u.as_str() != trait_unit.as_str() { types::cat5("move it to unit `", trait_unit.as_str(), "` or unit `", u.as_str(), "`") } else { types::cat3("move it to unit `", trait_unit.as_str(), "`") } },
            };
            self.rejected_impls.push(info);
            return;
        }
        let mut prev: Option<String> = None;
        for p in 0..self.trait_impls.len()
            invariant 0 <= p && p <= self.trait_impls.len(),
        {
            if !has_text(&prev) && self.trait_impls[p].trait_path.as_str() == tr.as_str() && types::overlaps(&self.trait_impls[p].head, &head, 100000) {
                prev = Some(types::text_in(&self.trait_impls[p].head, mp));
            }
        }
        match prev {
            None => {},
            Some(pt) => { self.help("E0311", span, types::cat4(types::cat5("`impl ", name.as_str(), " for ", ht.as_str(), "` overlaps `impl ").as_str(), name.as_str(), " for ", types::cat2(pt.as_str(), "`").as_str()).as_str(), "a trait has one impl for a type: remove one of them, or make their types differ"); self.overlapping_impls.push(info.span); self.rejected_impls.push(info); return; },
        }
        self.trait_impls.push(info);
    }
}

impl Parser {
    #[effects(alloc)]
    fn parse_fn(self: &mut Parser, attrs: Vec<ast::Attr>, d: usize) -> Option<ast::FnDef>
        requires d <= 256,
    {
        let lo: source::Span = self.span();
        let kind: ast::FnKind = if self.eat_kw("spec") {
            ast::FnKind::Spec
        } else if self.eat_kw("proof") {
            ast::FnKind::Proof
        } else {
            ast::FnKind::Exec
        };
        let is_proof: bool = match &kind {
            ast::FnKind::Exec => false,
            ast::FnKind::Spec => false,
            ast::FnKind::Proof => true,
        };
        self.bump();
        let name: ast::Ident = self.ident("function name")?;
        let mut generics: Vec<ast::TypeParam> = self.parse_generics(d);
        self.expect_p("(")?;
        let mut params: Vec<ast::Param> = Vec::new();
        let mut n: usize = self.left();
        while n > 0 && !self.is_p(")")
            decreases n,
        {
            n = n - 1;
            if self.is_kw("mut") {
                let msp: source::Span = self.bump();
                self.err_rep("E0210", msp, "`mut` parameters are not allowed", "copy into a `let mut` local inside the body", "");
            }
            let amp: bool = self.is_p("&");
            let short: bool = amp && self.t.is_kw(1, "self") || amp && self.t.is_kw(1, "mut") && self.t.is_kw(2, "self") || self.is_kw("self") && !self.t.is_p(1, ":");
            if short {
                let slo: source::Span = self.span();
                let form: u8 = if amp && self.t.is_kw(1, "mut") {
                    2
                } else if amp {
                    1
                } else {
                    0
                };
                let mut k: usize = self.left();
                while k > 0 && !self.is_kw("self")
                    decreases k,
                {
                    k = k - 1;
                    self.bump();
                }
                let sp: source::Span = slo.to(self.bump());
                let d0: diag::Diag = diag::new("E0228", sp, "the receiver needs its type");
                let mut pkind: ast::TypeKind = ast::TypeKind::Error;
                match &self.impl_ty {
                    None => self.diags.push(diag::fix(d0, "write `self: &T`, `self: &mut T` or `self: T` with the `impl` type", None)),
                    Some(t) => { let mut one: Vec<String> = Vec::new(); one.push(t.clone()); let named: ast::Type = ast::Type { kind: ast::TypeKind::Named(one, Vec::new()), span: sp }; let mut r: String = String::from("self: "); if form == 2 { r.push_str("&mut "); } else if form == 1 { r.push_str("&"); } r.push_str(t.as_str()); if form == 0 { pkind = named.kind; } else { pkind = ast::TypeKind::Ref(form == 2, Box::new(named)); } self.diags.push(diag::fix(d0, tick_write(r.as_str()).as_str(), Some(r))); },
                }
                params.push(ast::Param { name: ast::Ident { name: String::from("self"), span: sp }, ty: ast::Type { kind: pkind, span: sp } });
                if !self.eat_p(",") {
                    n = 0;
                }
            } else {
                let pname: ast::Ident = if self.is_kw("self") {
                    ast::Ident { name: String::from("self"), span: self.bump() }
                } else {
                    self.ident("parameter name")?
                };
                self.expect_p(":")?;
                let pty: ast::Type = self.parse_type(d);
                params.push(ast::Param { name: pname, ty: pty });
                if !self.eat_p(",") {
                    n = 0;
                }
            }
        }
        self.expect_p(")")?;
        let gspan2: Option<source::Span> = self.generics_span;
        let mut ret: ast::Ret = ast::Ret { name: None, ty: ast::Type { kind: ast::TypeKind::Unit, span: self.prev_span() } };
        if is_proof {
            if self.is_p("->") {
                let alo: source::Span = self.span();
                self.bump();
                self.parse_ret(d)?;
                self.err_rep_to("E0256", alo, "a `proof fn` has no return type: what it proves is its `ensures`", "remove the return type", "");
            }
        } else if self.eat_p("->") {
            ret = self.parse_ret(d)?;
        } else {
            let nsp: source::Span = self.prev_span();
        }
        self.parse_where(&mut generics, gspan2, d);
        let cl: Clauses = self.parse_clauses(d)?;
        let mut body: ast::Block = ast::Block { stmts: Vec::new(), tail: None, span: self.span() };
        if self.decl_ok && self.is_p(";") {
            self.bump();
        } else {
            self.decl_ok = false;
            body = self.parse_block(d)?;
        }
        let span: source::Span = lo.to(body.span);
        Some(ast::FnDef { kind: kind, name: name, generics: generics, attrs: attrs, params: params, ret: ret, pre: cl.pre, post: cl.post, measure: cl.measure, body: body, span: span })
    }
}

